head.b:skin:
:root{
  --red:#D62828;
  --orange:#F77F00;
  --green:#2A9D8F;
  --ink:#1D1D1D;
  --muted:#6B6B6B;
  --bg:#FFF8F0;
  --card:#FFFFFF;
  --border:#F0E4D8;
  --radius:14px;
}
*{box-sizing:border-box;}
html,body{margin:0;padding:0;background:var(--bg);color:var(--ink);font-family:'Inter',Arial,sans-serif;line-height:1.7;-webkit-text-size-adjust:100%;text-size-adjust:100%;}
h1,h2,h3,h4{font-family:'Poppins',Arial,sans-serif;line-height:1.25;margin:0 0 .5em;}
a{color:var(--red);text-decoration:none;}
a:hover{text-decoration:underline;}
img{max-width:100%;height:auto;border-radius:10px;display:block;}
.wrap{max-width:1180px;margin:0 auto;padding:0 20px;}

/* header */
.site-header{background:var(--card);border-bottom:1px solid var(--border);position:sticky;top:0;z-index:50;}
/* max-width 1220 + 20px side padding = same 1180px content width on desktop, but keeps a gutter on small screens */
.site-header .bar{display:flex;align-items:center;justify-content:space-between;gap:16px;max-width:1220px;padding:14px 20px;}
.logo{display:flex;align-items:center;gap:8px;font-family:'Poppins',Arial,sans-serif;font-weight:700;font-size:20px;color:var(--ink);}
.logo:hover{text-decoration:none;}
.logo svg{flex:0 0 auto;}
.logo span.accent{color:var(--red);}
.nav-toggle{display:none;background:none;border:0;font-size:24px;line-height:1;cursor:pointer;color:var(--ink);}
.main-nav{display:flex;gap:22px;flex-wrap:wrap;}
.main-nav a{color:var(--ink);font-weight:600;font-size:14px;}
.main-nav a:hover{color:var(--red);text-decoration:none;}

/* hero */
.hero{background:linear-gradient(135deg,var(--red),var(--orange));color:#fff;padding:48px 0;text-align:center;}
.hero h1{color:#fff;font-size:32px;margin-bottom:10px;}
.hero p{max-width:620px;margin:0 auto;opacity:.95;}

/* layout */
/* minmax(0,...) stops wide tables/embeds from stretching the grid past the screen */
.content-wrap{display:grid;grid-template-columns:minmax(0,2.1fr) minmax(0,1fr);gap:34px;max-width:1220px;padding:40px 20px;align-items:start;}
main,aside{min-width:0;}

/* cards / grid */
.card-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;}
.card{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;transition:transform .15s ease,box-shadow .15s ease;}
@media (hover:hover){
  .card:hover{transform:translateY(-3px);box-shadow:0 10px 24px rgba(0,0,0,.08);}
}
.card a.card-link{display:block;color:inherit;}
.card a.card-link:hover{text-decoration:none;}
.card .thumb{aspect-ratio:4/3;overflow:hidden;background:#eee;}
.card .thumb img{width:100%;height:100%;object-fit:cover;border-radius:0;}
.card .body{padding:14px 16px 18px;}
.card .cat{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--red);margin-bottom:6px;}
.card h3{font-size:16px;margin:0 0 6px;}
.card .meta{font-size:12px;color:var(--muted);}

/* category tiles */
.cat-tiles{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:14px;margin:30px 0;}
.cat-tile{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:16px 10px;text-align:center;font-size:13px;font-weight:600;color:var(--ink);}
.cat-tile:hover{border-color:var(--red);color:var(--red);text-decoration:none;}

/* article */
.post h1.post-title{font-size:30px;}
.byline{color:var(--muted);font-size:13px;margin-bottom:18px;display:flex;gap:10px;flex-wrap:wrap;align-items:center;}
.verified-badge{display:inline-flex;align-items:center;gap:6px;background:#EAF6F4;color:var(--green);border:1px solid #CDEAE6;padding:4px 10px;border-radius:999px;font-size:12px;font-weight:600;}
.breadcrumb{font-size:13px;color:var(--muted);margin-bottom:14px;}
.breadcrumb a{color:var(--muted);}
.toc{background:#FFF;border:1px solid var(--border);border-radius:var(--radius);padding:16px 18px;margin:20px 0;}
.toc h2{font-size:15px;margin-bottom:8px;}
.toc ul{margin:0;padding-left:18px;font-size:14px;}
.post-body{overflow-wrap:break-word;word-wrap:break-word;}
.post-body h2{font-size:22px;margin-top:34px;border-bottom:2px solid var(--border);padding-bottom:8px;}
.post-body h3{font-size:17px;margin-top:22px;}
/* keeps TOC jump targets from hiding under the sticky header */
.post-body h2,.post-body h3{scroll-margin-top:84px;}
.post-body iframe,.post-body video,.post-body embed,.post-body object{max-width:100%;}
.post-body pre{max-width:100%;overflow-x:auto;}
.disclaimer-box{background:#FFF4E5;border:1px solid #FFE1B3;border-radius:12px;padding:14px 16px;font-size:13.5px;color:#7A4E00;margin:20px 0;}

/* menu price table */
table.menu-table{width:100%;border-collapse:collapse;margin:18px 0;font-size:14.5px;background:#fff;border-radius:10px;overflow:hidden;border:1px solid var(--border);}
table.menu-table th{background:var(--red);color:#fff;text-align:left;padding:10px 12px;font-family:'Poppins',Arial,sans-serif;font-weight:600;}
table.menu-table td{padding:10px 12px;border-top:1px solid var(--border);}
table.menu-table tr:nth-child(even) td{background:#FFFBF5;}
table.menu-table td.price{font-weight:700;color:var(--red);white-space:nowrap;}
/* tables in posts are wrapped in this by the script below so they scroll sideways instead of breaking the page */
.table-scroll{width:100%;overflow-x:auto;margin:18px 0;}
.table-scroll > table{margin:0 !important;}

/* sidebar */
.widget{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:18px;margin-bottom:20px;}
.widget h2{font-size:15px;text-transform:uppercase;letter-spacing:.03em;margin-bottom:14px;}
.search-box input{width:100%;padding:10px 12px;border:1px solid var(--border);border-radius:8px;font-size:14px;}
.PopularPosts ul,.Label ul{list-style:none;margin:0;padding:0;}
.PopularPosts li,.Label li{padding:8px 0;border-bottom:1px solid var(--border);font-size:13.5px;}
.PopularPosts li:last-child,.Label li:last-child{border-bottom:0;}

/* footer */
.site-footer{background:var(--ink);color:#ddd;padding:34px 0;margin-top:30px;}
.site-footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:14px;align-items:center;}
.site-footer a{color:#ddd;font-size:13px;}
.footer-links{display:flex;gap:16px;flex-wrap:wrap;}
.copyright{font-size:12px;color:#999;}

/* =====================================================
   RESPONSIVE LAYER
   Desktop (1181px+) is unchanged. Everything below only
   applies on smaller screens.
   ===================================================== */

/* Small laptops: tighten nav so it stays on one line */
@media (max-width:1180px){
  .main-nav{gap:14px;}
  .main-nav a{font-size:13.5px;}
}

/* Tablets (landscape) and below: hamburger menu */
@media (max-width:1024px){
  .nav-toggle{display:flex;align-items:center;justify-content:center;width:44px;height:44px;margin-right:-8px;border-radius:8px;}
  .nav-toggle:focus-visible{outline:2px solid var(--red);outline-offset:2px;}
  .main-nav{display:none;position:absolute;top:100%;left:0;right:0;background:var(--card);flex-direction:column;flex-wrap:nowrap;gap:0;padding:6px 20px 12px;border-bottom:1px solid var(--border);box-shadow:0 12px 24px rgba(0,0,0,.08);max-height:calc(100vh - 72px);overflow-y:auto;}
  .main-nav.open{display:flex;}
  .main-nav a{display:block;padding:12px 0;font-size:15px;border-bottom:1px solid var(--border);}
  .main-nav a:last-child{border-bottom:0;}
  .cat-tiles{grid-template-columns:repeat(3,minmax(0,1fr));}
}

/* Tablets (portrait): single column, sidebar drops below posts */
@media (max-width:900px){
  .content-wrap{grid-template-columns:minmax(0,1fr);gap:28px;padding-top:28px;padding-bottom:28px;}
  .card-grid{grid-template-columns:repeat(2,minmax(0,1fr));}
  .hero{padding:36px 0;}
  .hero h1{font-size:27px;}
  .cat-tiles{margin:22px 0;}
  .cat-tile{display:flex;align-items:center;justify-content:center;min-height:64px;}
  .post h1.post-title{font-size:26px;}
  /* stops iOS from zooming in when the search box is tapped */
  .search-box input{font-size:16px;}
  /* remove Blogger's default section side-margins and the extra
     wrapper box Blogger adds around each widget, so content uses the full width */
  .section{margin-left:0;margin-right:0;}
  #main > .widget,#sidebar > .widget{background:none;border:0;border-radius:0;padding:0;margin:0;}
  .post-body iframe[src*="youtube"]{width:100%;height:auto;aspect-ratio:16/9;}
}

/* Phones */
@media (max-width:560px){
  .wrap{padding:0 16px;}
  .site-header .bar{padding:10px 16px;}
  .content-wrap{padding:22px 16px;gap:24px;}
  .logo{font-size:18px;}
  .logo svg{width:22px;height:22px;}
  .main-nav{padding:4px 16px 10px;}
  .hero{padding:28px 0;}
  .hero h1{font-size:23px;}
  .hero p{font-size:15px;}
  .cat-tiles{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:18px 0;}
  .cat-tile{padding:12px 8px;font-size:12.5px;min-height:56px;}
  .card-grid{grid-template-columns:minmax(0,1fr);gap:16px;}
  .post h1.post-title{font-size:23px;}
  .post-body h2{font-size:19px;margin-top:28px;}
  .post-body h3{font-size:16px;}
  .byline{gap:6px 10px;}
  .toc{padding:14px;}
  .disclaimer-box{padding:12px 14px;font-size:13px;}
  table.menu-table{font-size:13.5px;}
  table.menu-table th,table.menu-table td{padding:8px 10px;}
  .widget{padding:16px;}
  /* un-float images inserted by the Blogger post editor */
  .post-body .separator a,.post-body a[style*="float"]{float:none !important;margin-left:0 !important;margin-right:0 !important;}
  .post-body img{margin-left:auto;margin-right:auto;}
  .site-footer{padding:26px 0;}
  .site-footer .wrap{flex-direction:column;align-items:flex-start;}
  .footer-links{gap:10px 16px;}
}

head.script:
//
document.addEventListener('DOMContentLoaded', function(){
  var toggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.main-nav');
  if(toggle && nav){
    var closeNav = function(){
      nav.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
    };
    toggle.addEventListener('click', function(){
      var isOpen = nav.classList.toggle('open');
      toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });
    document.addEventListener('keydown', function(e){
      if(e.key === 'Escape' && nav.classList.contains('open')){ closeNav(); toggle.focus(); }
    });
    document.addEventListener('click', function(e){
      if(nav.classList.contains('open') && !nav.contains(e.target) && !toggle.contains(e.target)){ closeNav(); }
    });
  }

  // Wrap post tables so they scroll sideways on small screens
  var tables = document.querySelectorAll('.post-body table');
  for(var t = 0; t < tables.length; t++){
    var table = tables[t];
    if(table.parentNode.classList && table.parentNode.classList.contains('table-scroll')) continue;
    var scroller = document.createElement('div');
    scroller.className = 'table-scroll';
    table.parentNode.insertBefore(scroller, table);
    scroller.appendChild(table);
  }

  var body = document.querySelector('.post-body');
  var tocBox = document.querySelector('.toc-list');
  if(body && tocBox){
    var heads = body.querySelectorAll('h2');
    if(heads.length > 2){
      heads.forEach(function(h, i){
        var id = 'section-' + i;
        h.id = id;
        var li = document.createElement('li');
        var a = document.createElement('a');
        a.href = '#' + id;
        a.textContent = h.textContent;
        li.appendChild(a);
        tocBox.appendChild(li);
      });
    } else {
      var tocWrap = document.querySelector('.toc');
      if(tocWrap) tocWrap.style.display = 'none';
    }
  }
});

var HOME_SECTIONS = [
  {label: 'Restaurant Menus & Prices', title: 'Restaurant Menus &amp; Prices'},
  {label: 'Fast Food Menus', title: 'Fast Food Menus'},
  {label: 'Coffee & Drinks', title: 'Coffee &amp; Drinks'},
  {label: 'Secret Menus', title: 'Secret Menus'},
  {label: 'Breakfast Hours & Deals', title: 'Breakfast Hours &amp; Deals'},
  {label: 'Food Prices & Nutrition', title: 'Food Prices &amp; Nutrition'}
];
